89	     *  the one for the person's grade with the latest from-date on or before it, an undated rate
90	     *  applying from the beginning of time; at most one row, with its pct and to_date. */
91	    private static final String RATE_ON = "(SELECT r.pct, r.to_date FROM rate r WHERE r.sheet_id = ? AND r.grade = "
92	            + GRADE_ON + " AND (r.from_date IS NULL OR r.from_date <= CAST(? AS DATE))"
93	            + " ORDER BY r.from_date DESC NULLS LAST LIMIT 1)";
