149	     *  <period name>-<n>, or X-<n> when it is in no period. The sheet's row is locked first, so two
150	     *  claims opened at once get consecutive numbers. */
151	    public String numberInPeriod(String sheetId, long claimId, LocalDate date) {
152	        jdbc.update("UPDATE sheet SET claim_number = claim_number WHERE id = ?", sheetId);
153	        List<Object[]> period = jdbc.query("SELECT id, name FROM period WHERE sheet_id = ? AND from_date <= ?"
154	                + " AND to_date >= ? ORDER BY from_date LIMIT 1",
155	                (rs, i) -> new Object[] { rs.getLong("id"), rs.getString("name") }, sheetId, Date.valueOf(date),
156	                Date.valueOf(date));
157	        String key = period.isEmpty() ? "X" : "P" + period.get(0)[0];
158	        String prefix = period.isEmpty() ? "X" : (String) period.get(0)[1];
159	        if (jdbc.update("UPDATE claim_sequence SET last_no = last_no + 1 WHERE sheet_id = ? AND seq_key = ?",
160	                sheetId, key) == 0) {
161	            jdbc.update("INSERT INTO claim_sequence (sheet_id, seq_key, last_no) VALUES (?, ?, 1)", sheetId, key);
162	        }
163	        Long next = jdbc.queryForObject("SELECT last_no FROM claim_sequence WHERE sheet_id = ? AND seq_key = ?",
164	                Long.class, sheetId, key);
165	        String number = prefix + "-" + next;
166	        jdbc.update("UPDATE claim SET claim_no = ? WHERE id = ? AND sheet_id = ?", number, claimId, sheetId);
167	        return number;
168	    }
