175	    /** A claim's due now: its amount at the rate, in force on the claim's date, for the grade its person
176	     *  had on that date
177	     *  (the one with the latest from-date on or before it; an undated rate applies from the beginning
178	     *  of time; none applies when the claim's date is after that rate's to-date), rounded to two decimals by the claim's rounding (see {@link #rounding}), and at least the sheet's floor in force on the claim's date (a correction's, a
179	     *  negative amount's, has no floor); null when no rate applies. */
180	    public BigDecimal due(String sheetId, Claim claim) {
181	        List<BigDecimal> pct = jdbc.queryForList("SELECT a.pct FROM " + RATE_ON + " a"
182	                + " WHERE a.to_date IS NULL OR a.to_date >= CAST(? AS DATE)", BigDecimal.class, sheetId,
183	                sheetId, claim.personId(), claim.date(), claim.date(), claim.date());
184	        if (pct.isEmpty()) return null;
185	        BigDecimal due = new BigDecimal(claim.amount()).multiply(pct.get(0)).movePointLeft(2)
186	                .setScale(2, rounding(sheetId, claim));
187	        return new BigDecimal(claim.amount()).signum() < 0 ? due : due.max(settings.floor(sheetId, LocalDate.parse(claim.date())));
188	    }
