190	    /** How a claim's live figures round: half up when the claim is dated before the sheet's policy date
191	     *  (blank meaning the sheet's today), else half to even. A correction rounds by the date of the
192	     *  claim it corrects (its person's claim with that number), not its own. */
193	    public RoundingMode rounding(String sheetId, Claim claim) {
194	        String date = claim.date();
195	        if (claim.corrects() != null) {
196	            List<Date> corrected = jdbc.queryForList("SELECT claim_date FROM claim WHERE sheet_id = ? AND person_id = ?"
197	                    + " AND claim_no = ? ORDER BY id LIMIT 1", Date.class, sheetId, claim.personId(), claim.corrects());
198	            if (!corrected.isEmpty()) date = corrected.get(0).toLocalDate().toString();
199	        }
200	        List<Date> policy = jdbc.queryForList("SELECT COALESCE(policy_date, today) FROM sheet WHERE id = ?",
201	                Date.class, sheetId);
202	        if (policy.isEmpty()) return RoundingMode.HALF_EVEN;
203	        return LocalDate.parse(date).isBefore(policy.get(0).toLocalDate()) ? RoundingMode.HALF_UP
204	                : RoundingMode.HALF_EVEN;
205	    }
