207	    /** A claim's figure now: the due fixed when it was settled, else the one its last statement bound
208	     *  it to (not while PENDING; none when it bound it to n/a), else its live due; null when it has none. */
209	    public BigDecimal figure(String sheetId, Claim claim) {
210	        if (claim.due() != null) return new BigDecimal(claim.due());
211	        if (claim.bound() && claim.statedNa()) return null;
212	        if (claim.bound() && claim.statedDue() != null) return new BigDecimal(claim.statedDue());
213	        return due(sheetId, claim);
214	    }
