216	    /** A claim's due now: its figure, plus, while it is overdue (OPEN or PENDING and its due-by — fixed when it was
217	     *  created — before the sheet's today), the sheet's late percent in force on the claim's date of that figure for every full
218	     *  30 days it is overdue, rounded to two decimals by the claim's rounding. A statement never binds the charge:
219	     *  it keeps following the sheet's today until settling freezes it in. A correction (a negative amount)
220	     *  has no late charge. Null when it has no figure. */
221	    public BigDecimal dueNow(String sheetId, Claim claim) {
222	        BigDecimal figure = figure(sheetId, claim);
223	        if (figure == null || !claim.open() || new BigDecimal(claim.amount()).signum() < 0) {
224	            return figure;
225	        }
226	        List<Date> found = jdbc.queryForList("SELECT today FROM sheet WHERE id = ?", Date.class, sheetId);
227	        if (found.isEmpty()) return figure;
228	        LocalDate today = found.get(0).toLocalDate();
229	        LocalDate dueBy = LocalDate.parse(claim.dueBy());
230	        BigDecimal pct = settings.latePct(sheetId, LocalDate.parse(claim.date()));
231	        long periods = dueBy.isBefore(today) ? ChronoUnit.DAYS.between(dueBy, today) / 30 : 0;
232	        if (periods == 0 || pct == null || pct.signum() == 0) return figure;
233	        BigDecimal charge = figure.multiply(pct).multiply(BigDecimal.valueOf(periods)).movePointLeft(2)
234	                .setScale(2, rounding(sheetId, claim));
235	        return figure.add(charge);
236	    }
