342	    /** The status logs of the sheet's claims, by claim id: each a line per status it has had, oldest first,
343	     *  as "<STATUS> by <user> on <date> due=<due>" ('n/a' when it had no due). */
344	    public Map<String, List<String>> logs(String sheetId) {
