366	package net.officefloor.hq.app.claim;
367	
368	import java.math.BigDecimal;
369	import java.time.LocalDate;
370	import java.util.List;
371	import net.officefloor.hq.app.Audit;
372	import net.officefloor.hq.app.BadRequestException;
373	import net.officefloor.hq.app.period.PeriodGuard;
374	import net.officefloor.hq.app.period.PeriodRepository;
375	import net.officefloor.hq.app.rollup.Rollup;
376	import net.officefloor.hq.app.settings.SettingsRepository;
377	
378	/** A claim's status change (open, settle, approve, reject or void), shared by the single and the bulk actions. Every
379	 *  check is made before anything is written, so a refusal writes nothing to the store or the audit. */
380	final class ClaimStatusChange {
381	    private ClaimStatusChange() {
382	    }
383	
384	    static Claim apply(String id, long cid, String action, String by, ClaimRepository repository,
385	            PeriodRepository periods, SettingsRepository settings, Audit audit, Rollup rollup) throws BadRequestException {
386	        return apply(id, cid, action, null, by, repository, periods, settings, audit, rollup);
387	    }
388	
389	    static Claim apply(String id, long cid, String action, String reason, String by, ClaimRepository repository,
390	            PeriodRepository periods, SettingsRepository settings, Audit audit, Rollup rollup) throws BadRequestException {
391	        if ("resettle".equals(action == null ? "" : action.trim())) {
392	            return resettle(id, cid, by, repository, periods, settings, audit, rollup);
393	        }
394	        String to;
395	        List<String> from;
396	        String event;
397	        switch (action == null ? "" : action.trim()) {
398	            case "open" -> { to = "OPEN"; from = List.of("DRAFT"); event = "CLAIM_OPENED"; }
399	            case "settle" -> { to = "SETTLED"; from = List.of("OPEN"); event = "CLAIM_SETTLED"; }
400	            case "approve" -> { to = "SETTLED"; from = List.of("PENDING"); event = "CLAIM_APPROVED"; }
401	            case "reject" -> { to = "OPEN"; from = List.of("PENDING"); event = "CLAIM_REJECTED"; }
402	            case "void" -> { to = "VOID"; from = List.of("DRAFT", "OPEN", "PENDING"); event = "CLAIM_VOIDED"; }
403	            default -> throw new BadRequestException("no such action");
404	        }
405	        Claim found = repository.find(id, cid);
406	        if (found == null) {
407	            throw new BadRequestException("no such claim");
408	        }
409	        if (!from.contains(found.status())) {
410	            throw new BadRequestException("a " + found.status() + " claim cannot be moved to " + to);
411	        }
412	        PeriodGuard.open(periods, id, LocalDate.parse(found.date()));
413	        // Four eyes: whoever opened a claim cannot settle it.
414	        if (to.equals("SETTLED") && found.status().equals("OPEN") && by.equals(found.openedBy())) {
415	            throw new BadRequestException("the user who opened a claim cannot settle it");
416	        }
417	        // Only a steward approves or rejects a PENDING claim, and never one they opened themselves.
418	        if (found.status().equals("PENDING") && !to.equals("VOID")) {
419	            if (!settings.role(id, by).equals(SettingsRepository.STEWARD)) {
420	                throw new BadRequestException("only a steward can " + action.trim() + " a pending claim");
421	            }
422	            if (to.equals("SETTLED") && by.equals(found.openedBy())) {
423	                throw new BadRequestException("the user who opened a claim cannot approve it");
424	            }
425	        }
426	        String why = reason == null ? "" : reason.trim();
427	        if (event.equals("CLAIM_REJECTED") && why.isEmpty()) {
428	            throw new BadRequestException("give a reason to reject the claim");
429	        }
430	        // A clerk settles outright only a claim whose due is within the sheet's clerk limit ('n/a' is within
431	        // any); above it the claim goes to PENDING for a steward to approve or reject. A steward settles anything.
432	        if (to.equals("SETTLED") && found.status().equals("OPEN")
433	                && settings.role(id, by).equals(SettingsRepository.CLERK)) {
434	            BigDecimal limit = settings.clerkLimit(id);
435	            BigDecimal now = repository.dueNow(id, found);
436	            if (limit != null && now != null && now.compareTo(limit) > 0) {
437	                to = "PENDING";
438	                event = "CLAIM_PENDING";
439	            }
440	        }
441	        Rollup.Snapshot before = rollup.take(id);
442	        if (!repository.changeStatus(id, cid, from, to)) {
443	            throw new BadRequestException("a " + found.status() + " claim cannot be moved to " + to);
444	        }
445	        // Opening gives the sheet's next number; a rejected claim keeps its own; a voided claim keeps the number it had (never reused).
446	        String number = found.number();
447	        String openedBy = found.openedBy();
448	        if (found.status().equals("DRAFT") && to.equals("OPEN")) {
449	            number = repository.numbersPerPeriod(id)
450	                    ? repository.numberInPeriod(id, cid, LocalDate.parse(found.date()))
451	                    : repository.number(id, cid);
452	            repository.openedBy(id, cid, by);
453	            openedBy = by;
454	        }
455	        // Settling (or approving) fixes the claim's due as it is now: the figure its last statement bound it to
456	        // (a PENDING claim's is live), else its live due ('n/a' when its grade has no rate, which stays live), with its late charge frozen in.
457	        String due = null;
458	        String tail = event.equals("CLAIM_REJECTED") ? " reason=" + why : "";
459	        if (to.equals("SETTLED")) {
460	            BigDecimal now = repository.dueNow(id, found);
461	            repository.settleDue(id, cid, now);
462	            due = ClaimRepository.dueOf(now);
463	            tail = " due=" + (due == null ? "n/a" : due);
464	        }
465	        repository.log(id, cid, by);
466	        Claim changed = new Claim(found.id(), found.personId(), found.amount(), found.date(), found.note(), to,
467	                number, due, openedBy, found.stated(), found.statedDue(), found.corrects(), found.dueBy(),
468	                found.statedNa());
469	        audit.record(event + " sheet=" + id + " by=" + by + " person=" + repository.personName(id, found.personId())
470	                + " amount=" + changed.amount() + " date=" + changed.date() + Claim.auditNumber(number) + tail);
471	        rollup.record(id, by, before);
472	        return changed;
473	    }
474	
475	    /** A steward re-settles a SETTLED claim (not in a closed period): its due is frozen again at the figure it would
476	     *  have today as an open claim bound by no statement (today's rates, grades, floor and late charge). */
477	    private static Claim resettle(String id, long cid, String by, ClaimRepository repository, PeriodRepository periods,
478	            SettingsRepository settings, Audit audit, Rollup rollup) throws BadRequestException {
479	        Claim found = repository.find(id, cid);
480	        if (found == null) {
481	            throw new BadRequestException("no such claim");
482	        }
483	        if (!settings.role(id, by).equals(SettingsRepository.STEWARD)) {
484	            throw new BadRequestException("only a steward can re-settle a claim");
485	        }
486	        if (!found.status().equals("SETTLED")) {
487	            throw new BadRequestException("only a SETTLED claim can be re-settled");
488	        }
489	        PeriodGuard.open(periods, id, LocalDate.parse(found.date()));
490	        Claim live = new Claim(found.id(), found.personId(), found.amount(), found.date(), found.note(), "OPEN",
491	                found.number(), null, found.openedBy(), false, null, found.corrects(), found.dueBy(), false);
492	        BigDecimal now = repository.dueNow(id, live);
493	        Rollup.Snapshot before = rollup.take(id);
494	        repository.settleDue(id, cid, now);
495	        repository.log(id, cid, by);
496	        String old = found.due() == null ? "n/a" : found.due();
497	        String due = ClaimRepository.dueOf(now);
498	        Claim changed = new Claim(found.id(), found.personId(), found.amount(), found.date(), found.note(),
499	                found.status(), found.number(), due, found.openedBy(), found.stated(), found.statedDue(),
500	                found.corrects(), found.dueBy(), found.statedNa());
501	        audit.record("CLAIM_RESETTLED sheet=" + id + " by=" + by + " person=" + repository.personName(id, found.personId())
502	                + " amount=" + changed.amount() + " date=" + changed.date() + Claim.auditNumber(found.number())
503	                + " old=" + old + " new=" + (due == null ? "n/a" : due));
504	        rollup.record(id, by, before);
505	        return changed;
506	    }
507	}
