553	import org.springframework.stereotype.Service;
554	
555	/** The sheet's figures as shown: each person's claimed, due-total and overdue-total, and the sheet's
556	 *  claimed-total, due-total and overdue-total. A change takes them before it writes, then after its own audit lines records one ROLLUP
557	 *  line per person whose figures moved (people in the order they were added; a new person counts as
558	 *  moved), then a TOTALS line when the sheet's totals moved. */
559	@Service
560	public class Rollup {
561	
562	    /** A person's figures: claimed (two decimals), due-total (two decimals, or 'n/a') and overdue-total
563	     *  (two decimals: the sum of the dues now of their counting claims that are overdue, skipping those with none). */
564	    record Figures(String name, String claimed, String dueTotal, String overdueTotal) {
565	        boolean same(Figures other) {
566	            return other != null && claimed.equals(other.claimed) && dueTotal.equals(other.dueTotal)
567	                    && overdueTotal.equals(other.overdueTotal);
568	        }
569	    }
570	
571	    /** The figures of a sheet at one moment, people by id in the order they were added. */
572	    public record Snapshot(Map<Long, Figures> people, String claimedTotal, String dueTotal, String overdueTotal) {
573	    }
574	
575	    private final PersonRepository people;
576	    private final ClaimRepository claims;
577	    private final SheetRepository sheets;
578	    private final SettingsRepository settings;
579	    private final Audit audit;
580	
581	    public Rollup(PersonRepository people, ClaimRepository claims, SheetRepository sheets, SettingsRepository settings,
582	            Audit audit) {
583	        this.settings = settings;
584	        this.people = people;
585	        this.claims = claims;
586	        this.sheets = sheets;
587	        this.audit = audit;
588	    }
589	
590	    /** The sheet's figures now. A person's due-total is the sum of their counting claims' dues now (late charges included),
591	     *  skipping those with none; 'n/a' when no rate for the grade they have on the sheet's today is in force
592	     *  then and no counting claim keeps a fixed figure or has a due (at the grade it was claimed under). A due-total is at most the sheet's cap (an 'n/a' is not capped). The sheet's due-total skips 'n/a'. */
593	    public Snapshot take(String sheetId) {
594	        List<Person> everyone = people.list(sheetId);
595	        Map<Long, Figures> figures = new LinkedHashMap<>();
596	        BigDecimal claimedTotal = BigDecimal.ZERO.setScale(2);
597	        BigDecimal dueTotal = BigDecimal.ZERO.setScale(2);
598	        BigDecimal overdueTotal = BigDecimal.ZERO.setScale(2);
599	        if (!everyone.isEmpty()) {
600	            LocalDate today = sheets.today(sheetId);
601	            List<Claim> all = claims.list(sheetId);
602	            BigDecimal cap = settings.cap(sheetId);
603	            for (Person p : everyone) {
604	                BigDecimal claimed = BigDecimal.ZERO.setScale(2);
605	                BigDecimal due = BigDecimal.ZERO.setScale(2);
606	                BigDecimal overdue = BigDecimal.ZERO.setScale(2);
607	                boolean fixed = false;
608	                for (Claim c : all) {
609	                    if (c.personId() != p.id() || !c.counts(p.holds())) continue;
610	                    claimed = claimed.add(new BigDecimal(c.amount()));
611	                    fixed |= c.fixed();
612	                    BigDecimal now = claims.dueNow(sheetId, c);
613	                    if (now != null) due = due.add(now);
614	                    if (now != null && c.open() && LocalDate.parse(c.dueBy()).isBefore(today)) overdue = overdue.add(now);
615	                    fixed |= now != null;
616	                }
617	                boolean shown = fixed || claims.rated(sheetId, p.id(), today);
618	                due = SettingsRepository.capped(due, cap);
619	                figures.put(p.id(), new Figures(p.name(), claimed.toPlainString(),
620	                        shown ? due.toPlainString() : "n/a", overdue.toPlainString()));
621	                claimedTotal = claimedTotal.add(claimed);
622	                if (shown) dueTotal = dueTotal.add(due);
623	                overdueTotal = overdueTotal.add(overdue);
624	            }
625	        }
626	        return new Snapshot(figures, claimedTotal.toPlainString(), dueTotal.toPlainString(), overdueTotal.toPlainString());
627	    }
628	
629	    /** Record the lines for whatever figures moved since {@code before}. */
630	    public void record(String sheetId, String by, Snapshot before) {
631	        Snapshot after = take(sheetId);
632	        for (Map.Entry<Long, Figures> e : after.people().entrySet()) {
633	            Figures now = e.getValue();
634	            if (now.same(before.people().get(e.getKey()))) continue;
635	            audit.record("ROLLUP sheet=" + sheetId + " by=" + by + " person=" + now.name() + " claimed="
636	                    + now.claimed() + " due-total=" + now.dueTotal() + " overdue-total=" + now.overdueTotal());
637	        }
638	        if (!after.claimedTotal().equals(before.claimedTotal()) || !after.dueTotal().equals(before.dueTotal())
639	                || !after.overdueTotal().equals(before.overdueTotal())) {
640	            audit.record("TOTALS sheet=" + sheetId + " by=" + by + " claimed-total=" + after.claimedTotal()
641	                    + " due-total=" + after.dueTotal() + " overdue-total=" + after.overdueTotal());
642	        }
643	    }
644	}
