1	import { useState, type ChangeEvent } from 'react';
2	import { useMutation, useQueryClient } from '@tanstack/react-query';
3	import { postJson } from '../../api/http';
4	import { useSingleFlight } from '../../query/useSingleFlight';
5	import { PERSON_ROW_SPAN, PersonCells, PersonColumnHead, PersonDetail } from '../../slots/defs/personRow';
6	import { SheetBody } from '../../slots/defs/sheetBody';
7	import { gradeOn, holdsById, usePeople } from '../people/usePeople';
8	import { periodOf, usePeriods } from '../periods/usePeriods';
9	import { rateFor, useRates } from '../rates/useRates';
10	import { claimDueNow, isOverdue } from '../overdue/useOverdue';
11	import { useSettings } from '../settings/useSettings';
12	import { useSheetToday } from '../today/useSheetToday';
13	import { claimed, claimsKey, useClaims, type Claim } from './useClaims';
14	import { useClaimSelection } from './useClaimSelection';
15	
16	/** A person's claimed: the sum of their counted (OPEN, PENDING or SETTLED; an open one dated within a hold only when a statement binds it) claims' amounts. */
17	function PersonClaimed({ sheetId, personId }: { sheetId: string; personId: number }) {
18	  const claims = useClaims(sheetId);
19	  const people = usePeople(sheetId);
20	  return (
21	    <td data-testid="person-claimed">
22	      {claimed((claims.data ?? []).filter((c) => c.personId === personId), holdsById(people.data))}
23	    </td>
24	  );
25	}
26	
27	type ClaimAction = 'open' | 'settle' | 'approve' | 'reject' | 'void' | 'resettle';
28	
29	/** A claim's status changes; the server refuses one its status does not allow, a settle by the user
30	 *  who opened the claim, and an approve or reject by anyone but a steward (an approve also by the
31	 *  user who opened the claim), and a re-settle by anyone but a steward or of a claim not SETTLED. A reject takes the reason typed on the claim's row. */
32	const ACTIONS: [ClaimAction, string][] = [
33	  ['open', 'Open'],
34	  ['settle', 'Settle'],
35	  ['approve', 'Approve'],
36	  ['reject', 'Reject'],
37	  ['void', 'Void'],
38	  ['resettle', 'Re-settle'],
39	];
40	
41	/** A person's claims, newest first, under their row, with a form that adds a claim, or edits one
42	 *  when its editor is open. A blank date takes the sheet's today. A negative amount is a correction:
43	 *  the form names, by number, the settled claim of the same person it corrects. */
44	function PersonClaims({ sheetId, personId }: { sheetId: string; personId: number }) {
45	  const claims = useClaims(sheetId);
46	  const people = usePeople(sheetId);
47	  const rates = useRates(sheetId);
48	  const settings = useSettings(sheetId).data;
49	  const today = useSheetToday(sheetId).data?.today;
50	  const periods = usePeriods(sheetId);
51	  const queryClient = useQueryClient();
52	  const selection = useClaimSelection(sheetId);
53	  const [editing, setEditing] = useState<number | null>(null);
54	  const [refused, setRefused] = useState<number | null>(null);
55	  const [amount, setAmount] = useState('');
56	  const [date, setDate] = useState('');
57	  const [note, setNote] = useState('');
58	  const [corrects, setCorrects] = useState('');
59	  const [reasons, setReasons] = useState<Record<number, string>>({});
60	  const [targets, setTargets] = useState<Record<number, string>>({});
61	
62	  const clearForm = () => {
63	    setEditing(null);
64	    setAmount('');
65	    setDate('');
66	    setNote('');
67	    setCorrects('');
68	  };
69	
70	  const submitOnce = useSingleFlight();
71	  const save = useMutation({
72	    mutationFn: (f: { id: number | null; amount: string; date: string; note: string; corrects: string }) => {
73	      const sheet = `/api/sheets/${encodeURIComponent(sheetId)}`;
74	      const path = f.id === null ? `${sheet}/people/${personId}/claims` : `${sheet}/claims/${f.id}`;
75	      return postJson<Claim>(path, { amount: f.amount, date: f.date, note: f.note, corrects: f.corrects });
76	    },
77	    onSuccess: async () => {
78	      clearForm();
79	      await queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
80	    },
81	  });
82	
83	  // A status change (open, settle, approve, reject, void) of one claim; a refusal shows on that claim's row.
84	  const action = useMutation({
85	    mutationFn: (a: { id: number; action: ClaimAction; reason: string }) =>
86	      postJson<Claim>(`/api/sheets/${encodeURIComponent(sheetId)}/claims/${a.id}/${a.action}`, { reason: a.reason }),
87	    onSuccess: (_, a) => {
88	      if (a.action === 'reject') setReasons((r) => ({ ...r, [a.id]: '' }));
89	    },
90	    onSettled: async () => {
91	      await queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
92	    },
93	  });
94	
95	  // A steward moves a DRAFT, OPEN or PENDING claim to the person chosen on its row; a refusal shows on that claim's row.
96	  const reassign = useMutation({
97	    mutationFn: (r: { id: number; personId: number | null }) =>
98	      postJson<Claim>(`/api/sheets/${encodeURIComponent(sheetId)}/reassign`, { claimId: r.id, personId: r.personId }),
99	    onSuccess: (_, r) => setTargets((t) => ({ ...t, [r.id]: '' })),
100	    onSettled: async () => {
101	      await queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
102	    },
103	  });
104	
105	  const move = (id: number) => {
106	    setRefused(null);
107	    action.reset();
108	    reassign.reset();
109	    const target = targets[id] ?? '';
110	    reassign.mutate({ id, personId: target === '' ? null : Number(target) });
111	  };
112	
113	  const act = (id: number, a: ClaimAction) => {
114	    setRefused(null);
115	    action.reset();
116	    reassign.reset();
117	    action.mutate({ id, action: a, reason: a === 'reject' ? reasons[id] ?? '' : '' });
118	  };
119	
120	  // Only a DRAFT can be edited: editing any other claim is refused on its row and opens no editor
121	  // (to change an open claim, void it and add a new one).
122	  const openEditor = (c: Claim) => {
123	    save.reset();
124	    action.reset();
125	    reassign.reset();
126	    if (c.status !== 'DRAFT') {
127	      setRefused(c.id);
128	      return;
129	    }
130	    setRefused(null);
131	    setEditing(c.id);
132	    setAmount(c.amount);
133	    setDate(c.date);
134	    setNote(c.note);
135	    setCorrects(c.corrects === null ? '' : String(c.corrects));
136	  };
137	
138	  const cancel = () => {
139	    save.reset();
140	    clearForm();
141	  };
142	
143	  const field = (set: (v: string) => void) => (e: ChangeEvent<HTMLInputElement>) => {
144	    set(e.target.value);
145	    save.reset();
146	  };
147	
148	  const mine = (claims.data ?? []).filter((c) => c.personId === personId);
149	  // A claim's due: the one fixed when it was settled, else the one its last statement bound it to,
150	  // else its amount at the rate in force on its date for the grade its person had on that date, at least the sheet's floor
151	  // ('n/a' when none applies), with its late charge while it is overdue.
152	  const person = people.data?.find((p) => p.id === personId);
153	
154	  return (
155	    <tr>
156	      <td colSpan={PERSON_ROW_SPAN}>
157	        <form
158	          data-testid="claim-form"
159	          onSubmit={(e) => {
160	            e.preventDefault();
161	            setRefused(null);
162	            submitOnce(() => {
163	              save.reset();
164	              return save.mutateAsync({ id: editing, amount, date, note, corrects });
165	            });
166	          }}
