import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { heldOn, type Hold } from '../people/usePeople';

/** A claim's status: DRAFT -> OPEN -> SETTLED; a clerk's settle above the clerk limit goes to PENDING
 *  instead, which a steward approves (SETTLED) or rejects (OPEN again); a DRAFT, OPEN or PENDING claim
 *  can become VOID. */
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID';

/** A claim: its amount with two decimals, its date (yyyy-mm-dd), its note, its status, its number on
 *  the sheet (given when it is opened: 1, 2, ... or, under period numbering, <period>-<n> or X-<n>; null while a draft and once void) and the due fixed when it was
 *  settled (null unless settled while its grade had a rate: its due is then live, from the rates), and
 *  who opened it (null until it is opened), whether its person's last statement bound it, and the figure
 *  it was bound to (null when not bound, or bound with no figure: its due then stays live), and, for a
 *  correction (a negative amount), the number of the settled claim of the same person it corrects, and
 *  its due-by (yyyy-mm-dd), fixed when it was created from the terms of its person's grade then (else the
 *  sheet's terms), and its status log: a line per status it has had, oldest first, as
 *  "<STATUS> by <user> on <date> due=<due>" with the sheet's today and its due at that moment, and whether
 *  its last statement bound it to n/a (the rate that would apply to it had ended: its due stays n/a). */
export type Claim = {
  id: number;
  personId: number;
  amount: string;
  date: string;
  note: string;
  status: ClaimStatus;
  number: string | null;
  due: string | null;
  openedBy: string | null;
  stated: boolean;
  statedDue: string | null;
  corrects: string | null;
  dueBy: string;
  statedNa: boolean;
  log: string[];
};

/** Whether a claim is open: OPEN, or PENDING (handled like OPEN everywhere but its statement binding). */
export function isOpen(c: Claim): boolean {
  return c.status === 'OPEN' || c.status === 'PENDING';
}

/** A claim's fixed figure: the due frozen when it was settled, else the one its last statement bound
 *  it to (a PENDING claim is not bound; 'n/a' when it bound it to n/a); null when its due is live. */
export function fixedDue(c: Claim): string | null {
  if (c.due !== null) return c.due;
  if (!isBound(c)) return null;
  return c.statedNa ? 'n/a' : c.statedDue;
}

/** Whether a claim counts toward claimed and every live total, given the people's holds by person id:
 *  only open (OPEN or PENDING) and SETTLED claims do, and an open claim dated within one of its person's
 *  holds does not, unless a statement binds it. */
export function counts(c: Claim, holds: ReadonlyMap<number, Hold[]>): boolean {
  return c.status === 'SETTLED' || (isOpen(c) && (isBound(c) || !heldOn(holds.get(c.personId), c.date)));
}

/** Whether its person's last statement binds a claim now: it was stated and is not PENDING. */
export function isBound(c: Claim): boolean {
  return c.stated && c.status !== 'PENDING';
}

export function claimsKey(sheetId: string) {
  return ['sheet', sheetId, 'claims'];
}

/** Every claim on the sheet, newest first. */
export function useClaims(sheetId: string) {
  return useQuery({
    queryKey: claimsKey(sheetId),
    queryFn: async () => {
      const res = await getJson<{ claims: Omit<Claim, 'log'>[]; logs: Record<string, string[]> }>(
        `/api/sheets/${encodeURIComponent(sheetId)}/claims`,
      );
      return res.claims.map((c): Claim => ({ ...c, log: res.logs[String(c.id)] ?? [] }));
    },
  });
}

/** The sum of the amounts of those of these claims that count (given the people's holds by person id),
 *  with two decimals (added up in cents, so no rounding drift). */
export function claimed(claims: Claim[], holds: ReadonlyMap<number, Hold[]>): string {
  const cents = claims.filter((c) => counts(c, holds)).reduce((sum, c) => sum + Math.round(Number(c.amount) * 100), 0);
  return (cents / 100).toFixed(2);
}
import { counts, fixedDue, isOpen, useClaims, type Claim } from '../claims/useClaims';
import { gradeOn, holdsById, usePeople } from '../people/usePeople';
import { due, isCorrection, rateFor, sumDues, useRates, withCharge } from '../rates/useRates';
import { settingOn, useSettings, type Settings } from '../settings/useSettings';
import { useSheetToday } from '../today/useSheetToday';

/** Whether a claim is overdue: it is open (OPEN or PENDING) and its due-by is before the sheet's today. */
export function isOverdue(c: Claim, today: string): boolean {
  return isOpen(c) && c.dueBy < today;
}

/** Whether a claim's live figures (its rate step and late charge) round half up: when the claim is
 *  dated before the sheet's policy date (blank meaning the sheet's today); else they round half to
 *  even. A correction rounds by the date of the claim it corrects (its person's claim with that
 *  number), not its own. Half to even until the settings and the sheet's today are loaded. */
export function roundsHalfUp(c: Claim, claims: Claim[] | undefined, settings: Settings | undefined, today: string | undefined): boolean {
  const policy = settings === undefined ? undefined : settings.policyDate ?? today;
  if (policy === undefined) return false;
  const corrected = c.corrects === null
    ? undefined
    : (claims ?? []).find((o) => o.personId === c.personId && o.number === c.corrects);
  return (corrected?.date ?? c.date) < policy;
}

/** A claim's due now: its figure (a settled claim's frozen due, else the one its last statement
 *  bound it to, else its floored live due), plus, while it is overdue, the sheet's late percent in force on
 *  the claim's date of
 *  that figure for every full 30 days it is overdue, rounded like a due. The charge is never bound by
 *  a statement: it follows the sheet's today until settling freezes it in. A correction (a negative
 *  amount) has no late charge. Just the figure until the settings and the sheet's today are loaded. */
export function dueNow(c: Claim, figure: string, settings: Settings | undefined, today: string | undefined, halfUp: boolean): string {
  if (settings === undefined || today === undefined || !isOverdue(c, today) || isCorrection(c.amount)) {
    return figure;
  }
  const days = (Date.parse(`${today}T00:00:00Z`) - Date.parse(`${c.dueBy}T00:00:00Z`)) / 86_400_000;
  return withCharge(figure, settingOn(settings, 'late-pct', c.date) ?? '0.00', Math.floor(days / 30), halfUp);
}

/** A claim's due now (see `dueNow`) from its fixed figure, else its live due at this rate (a
 *  two-decimal percent; undefined when none applies) and the floor in force on its date, every rounding by
 *  the claim's policy (see `roundsHalfUp`) — the other claims on the sheet are what a correction is looked up in.
 *  No floor until the settings are loaded. */
export function claimDueNow(c: Claim, claims: Claim[] | undefined, pct: string | undefined,
  settings: Settings | undefined, today: string | undefined): string {
  const up = roundsHalfUp(c, claims, settings, today);
  const floor = settings === undefined ? undefined : settingOn(settings, 'floor', c.date) ?? undefined;
  return dueNow(c, fixedDue(c) ?? due(c.amount, pct, floor, up), settings, today, up);
}

/** Each person's overdue figures, by person id: how many of their claims that count are overdue, and
 *  the sum of those claims' dues now (a stated claim's bound figure, else its live due, with its late
 *  charge), skipping
 *  those with none. Empty until the terms and the sheet's today are loaded. */
export function useOverdue(sheetId: string): Map<number, { count: number; total: string }> {
  const people = usePeople(sheetId);
  const claims = useClaims(sheetId);
  const rates = useRates(sheetId);
  const settings = useSettings(sheetId).data;
  const today = useSheetToday(sheetId).data?.today;
  const holds = holdsById(people.data);
  const figures = new Map<number, { count: number; total: string }>();
  if (settings === undefined || today === undefined) return figures;
  for (const p of people.data ?? []) {
    const overdue = (claims.data ?? []).filter(
      (c) => c.personId === p.id && counts(c, holds) && isOverdue(c, today),
    );
    figures.set(p.id, {
      count: overdue.length,
      total: sumDues(overdue.map((c) =>
        claimDueNow(c, claims.data, rateFor(rates.data, gradeOn(p, c.date), c.date), settings, today))),
    });
  }
  return figures;
}
import { PersonCells, PersonColumnHead } from '../../slots/defs/personRow';
import { SheetBody } from '../../slots/defs/sheetBody';
import { sumDues } from '../rates/useRates';
import { useOverdue } from './useOverdue';

/** A person's overdue count and overdue-total: their claims that count and are overdue, and the sum
 *  of those claims' figures. */
function PersonOverdue({ sheetId, personId }: { sheetId: string; personId: number }) {
  const figures = useOverdue(sheetId).get(personId);
  return (
    <>
      <td data-testid="person-overdue-count">{figures?.count ?? ''}</td>
      <td data-testid="person-overdue-total">{figures?.total ?? ''}</td>
    </>
  );
}

/** The sheet's overdue count and overdue-total: everyone's added up. */
function SheetOverdue({ sheetId }: { sheetId: string }) {
  const figures = [...useOverdue(sheetId).values()];
  return (
    <p>
      Overdue: <strong data-testid="rollup-overdue-count">{figures.reduce((n, f) => n + f.count, 0)}</strong>,
      total <strong data-testid="rollup-overdue-total">{sumDues(figures.map((f) => f.total))}</strong>
